mapper.select:
SELECT COUNT(*) FROM study_room_steps
WHERE study_room_id=#{roomId} AND id=#{stepId}
  AND run_id=(SELECT current_run_id FROM study_rooms WHERE id=study_room_id)

mapper.update:
UPDATE study_rooms SET current_step_id=#{stepId}, version=version+1, updated_at=CURRENT_TIMESTAMP
WHERE id=#{roomId} AND user_id=#{userId}
  AND EXISTS (
    SELECT 1 FROM study_room_steps
    WHERE id=#{stepId} AND study_room_id=#{roomId} AND run_id=current_run_id
  )
